mapper.select:
SELECT r.id, r.name, r.media_type AS mediaType, r.channel, r.rate_card AS rateCard, r.discount_policy AS discountPolicy, r.contact_person AS contactPerson, r.contact_phone AS contactPhone, r.cooperation_status AS cooperationStatus, r.status, r.business_entity_id AS businessEntityId, r.create_time AS createTime, be.name AS businessEntityName FROM ad_downstream_media r LEFT JOIN ad_business_entity be ON be.id = r.business_entity_id AND be.deleted = 0 WHERE r.deleted = 0 AND r.organization_id = #{request.organizationId}
AND r.name LIKE CONCAT('%', #{request.keyword}, '%')
AND r.media_type = #{request.mediaType}
AND r.status = #{request.status}
AND r.business_entity_id = #{request.businessEntityId}
AND r.business_entity_id IN
#{eid}
ORDER BY r.create_time DESC
